(7303641, 1138882, 97760, '<td valign="top">Yes!!!!!</td>', 'Yes!!!!!', '2015-01-18 07:08:22.000000', NULL, 0),
(7303743, 1138914, 114969, '<td valign="top">Great idea Mark! It looks like Riley still loves you: who knows, he may even appreciates your solidarity :) I hope everything went well with the stitches, so that you can both enjoy the much deserved ribbon happily.</td>', 'Great idea Mark! It looks like Riley still loves you: who knows, he may even appreciates your solidarity :) I hope everything went well with the stitches, so that you can both enjoy the much deserved ribbon happily.', '2015-01-18 13:07:24.000000', NULL, 0),
(7303744, 1138852, 114969, '<td valign="top">If you keep taking photos of your dog all year long, and if they are all this good, he is going to be immensely proud! Make sure he doesn''t start a gallery in the garden, to impress the neighborhood :) Great work, as other said, the point of view makes it all, great impact.</td>', 'If you keep taking photos of your dog all year long, and if they are all this good, he is going to be immensely proud! Make sure he doesn''t start a gallery in the garden, to impress the neighborhood :) Great work, as other said, the point of view makes it all, great impact.', '2015-01-18 13:10:46.000000', NULL, 0),
(7303746, 1138902, 114969, '<td valign="top">Oh yes, creativity! I am always happy when I see you exploring new areas Alessandro, please keep doing so! One of my top votes.</td>', 'Oh yes, creativity! I am always happy when I see you exploring new areas Alessandro, please keep doing so! One of my top votes.', '2015-01-18 13:13:36.000000', NULL, 0),
(7303748, 1138745, 114969, '<td valign="top">Beautiful Margaret. The fog in those majestic trees creates a fascinating mood, that you captured perfectly. I would love to wander on this path, thanks for sharing!</td>', 'Beautiful Margaret. The fog in those majestic trees creates a fascinating mood, that you captured perfectly. I would love to wander on this path, thanks for sharing!', '2015-01-18 13:19:06.000000', NULL, 0);
